package com.aoo.bcg.admin;import java.sql.*;import java.time.*;import java.util.*;
public final class JdbcAdminAuthorizationAudit implements AdminAuthorizationAudit{private final JdbcAdminResourceRepository.ConnectionFactory connections;public JdbcAdminAuthorizationAudit(JdbcAdminResourceRepository.ConnectionFactory c){connections=Objects.requireNonNull(c);}@Override public void record(String requestId,long operatorId,String permission,String method,String path,boolean allowed,Instant at){String sql="INSERT INTO admin_authorization_audit(request_id,operator_id,permission_code,http_method,request_path,decision,occurred_at) VALUES(?,?,?,?,?,?,?)";try(var c=connections.open();var q=c.prepareStatement(sql)){q.setString(1,requestId);q.setLong(2,Math.max(0,operatorId));q.setString(3,permission);q.setString(4,method);q.setString(5,path);q.setString(6,allowed?"ALLOWED":"DENIED");q.setTimestamp(7,Timestamp.from(at));q.executeUpdate();}catch(Exception e){throw new IllegalStateException("cannot audit admin authorization",e);}}}
